// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address admin;

    function setUp() public {
        admin = address(this);
        c = new Owned();
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.prank(admin);
        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeWithSignature("setOwner(address)", newOwner)
        );
        assertTrue(ok && abi.decode(ret, (bool)), "setOwner must return true on success");
    }
}
